import { useEffect, useState } from 'react';
import { db, getMeta, setMeta } from '@/db/schema.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { Seal } from './art/Seal.js';
import { runningTrial } from './trial.js';
import { useBilling } from './state.js';
import styles from './ProMark.module.css';

/** How long the one-time "Part of your Pro trial" tip stays (uiux offers spec §2.7). */
export const PRO_TIP_MS = 4000;

/** The small gold "Pro" pill (C2): seal and word, in the trial's gold. */
export function ProMark({ size = 'sm' }: { size?: 'sm' | 'md' }): React.JSX.Element {
  return (
    <span className={cx(styles.mark, size === 'md' && styles.md)}>
      <Seal size={size === 'md' ? 14 : 12} />
      {t('promark.label')}
    </span>
  );
}

/**
 * The Pro mark on a Pro feature while the account is in its trial
 * (trial-offers design §2.1): Lex's header, Words worth keeping, Say it,
 * Use it in a sentence, voice input, a notebook beyond Free. Nothing
 * outside a trial. The first one the learner meets carries a one-line
 * tip, "Part of your Pro trial", once ever on this device (meta
 * `trialNotes.markLineSeen`), for a few seconds or until tapped.
 */
export function TrialProMark({
  size = 'sm',
  tip = false,
}: {
  size?: 'sm' | 'md';
  tip?: boolean;
}): React.JSX.Element | null {
  const state = useBilling((s) => s.state);
  const [now] = useState(() => new Date());
  const inTrial = runningTrial(state, now) !== undefined;
  const [showTip, setShowTip] = useState(false);

  useEffect(() => {
    if (!inTrial || !tip) return;
    let live = true;
    let timer: number | undefined;
    void db
      .transaction('rw', db.meta, async () => {
        const notes = await getMeta('trialNotes');
        if (notes.markLineSeen === true) return false;
        await setMeta('trialNotes', { ...notes, markLineSeen: true });
        return true;
      })
      .then((first) => {
        if (!live || !first) return;
        setShowTip(true);
        timer = window.setTimeout(() => {
          setShowTip(false);
        }, PRO_TIP_MS);
      })
      .catch(() => undefined);
    return () => {
      live = false;
      window.clearTimeout(timer);
    };
  }, [inTrial, tip]);

  if (!inTrial) return null;
  return (
    <span className={styles.wrap}>
      <ProMark size={size} />
      {showTip && (
        <button
          type="button"
          className={styles.tip}
          role="status"
          onClick={() => {
            setShowTip(false);
          }}
        >
          {t('promark.tip')}
        </button>
      )}
    </span>
  );
}
